def toposort(deps):
    # Create a copy of the dependency map to avoid modifying the input
    # and identify all unique nodes in the graph
    graph = {}
    all_nodes = set()
    for node, dependencies in deps.items():
        all_nodes.add(node)
        graph[node] = list(dependencies)
        for dep in dependencies:
            all_nodes.add(dep)

    # Ensure every node exists in the graph dictionary
    for node in all_nodes:
        if node not in graph:
            graph[node] = []

    # Build adjacency list (who depends on me) and in-degree counts
    # Note: The input 'deps' is: node -> [list of things it depends on]
    # We need: dependency -> [list of things that depend on it]
    adj = defaultdict(list)
    in_degree = {node: 0 for node in all_nodes}

    for node, dependencies in graph.items():
        for dep in dependencies:
            adj[dep].append(node)
            in_degree[node] += 1

    # Kahn's algorithm with a min-heap (simulated by sorted list/set)
    # to ensure lexicographical order for nodes with 0 in-degree.
    # Since we need the smallest alphabetically, we use a sorted list or a heap.
    # Python's heapq is perfect here.
    import heapq

    queue = [node for node in all_nodes if in_degree[node] == 0]
    heapq.heapify(queue)

    result = []
    while queue:
        u = heapq.heappop(queue)
        result.append(u)

        for v in adj[u]:
            in_degree[v] -= 1
            if in_degree[v] == 0:
                heapq.heappush(queue, v)

    if len(result) != len(all_nodes):
        raise ValueError("Cycle detected in dependencies")

    return result

