class LRUCache:
    def __init__(self, capacity: int):
        if capacity < 1:
            raise ValueError("Capacity must be at least 1")
        self.capacity = capacity
        self.cache = OrderedDict()

    def get(self, key: int):
        if key not in self.cache:
            return None
        self.cache.move_to_end(key)
        return self.cache[key]

    def put(self, key: int, value: any):
        if key in self.cache:
            self.cache.move_to_end(key)
        self.cache[key] = value
        if len(self.cache) > self.capacity:
            self.cache.popitem(last=False)

    def __len__(self):
        return len(self.cache)

    def keys(self):
        return list(self.cache.keys())

def flatten_dict(d, sep="."):
    """
    Flattens a nested dictionary into a single-level dictionary.

    Args:
        d (dict): The dictionary to flatten.
        sep (str): The separator to join keys.

    Returns:
        dict: The flattened dictionary.
    """
    result = {}

    def _flatten(current_dict, current_prefix):
        for key, value in current_dict.items():
            new_key = f"{current_prefix}{sep}{key}" if current_prefix else key

            if isinstance(value, dict) and value:
                _flatten(value, new_key)
            else:
                result[new_key] = value

    # Special handling for empty dictionaries to ensure they are kept as empty dicts
    # and to handle the root level correctly.
    for key, value in d.items():
        if isinstance(value, dict) and not value:
            result[key] = {}
        elif isinstance(value, dict):
            _flatten(value, key)
        else:
            result[key] = value

    return result

def median(values):
    if not values:
        raise ValueError("List is empty")
    s = sorted(values)
    n = len(s)
    mid = n // 2
    if n % 2 == 0:
        return (s[mid - 1] + s[mid]) / 2
    else:
        return s[mid]

def chunked(items, size):
    if size < 1:
        raise ValueError("Size must be at least 1")
    return [list(items[i:i + size]) for i in range(0, len(items), size)]

def append_unique(item, bucket=None):
    if bucket is None:
        bucket = []
    if item not in bucket:
        bucket.append(item)
    return bucket

