class TTLCache:
    def __init__(self, capacity, ttl, clock=time.monotonic):
        if capacity < 1:
            raise ValueError("Capacity must be at least 1")
        if ttl <= 0:
            raise ValueError("TTL must be greater than 0")

        self.capacity = capacity
        self.ttl = ttl
        self.clock = clock

        # Stores key -> (value, expiry_time)
        self.cache = {}
        # Stores keys in order of access (LRU)
        self.order = collections.OrderedDict()

    def _is_expired(self, expiry_time):
        return self.clock() >= expiry_time

    def _remove_expired(self):
        expired_keys = []
        for key, (value, expiry_time) in self.cache.items():
            if self._is_expired(expiry_time):
                expired_keys.append(key)

        for key in expired_keys:
            del self.cache[key]
            del self.order[key]

    def put(self, key, value):
        # Remove expired before adding new
        self._remove_expired()

        if key in self.cache:
            self.order.move_to_end(key)

        expiry = self.clock() + self.ttl
        self.cache[key] = (value, expiry)
        self.order[key] = True

        # Eviction logic
        while len(self.cache) > self.capacity:
            # _remove_expired is called at start of put, 
            # so we just need to drop the LRU
            oldest_key = next(iter(self.order))
            del self.cache[oldest_key]
            del self.order[oldest_key]

    def get(self, key):
        if key not in self.cache:
            return None

        value, expiry_time = self.cache[key]

        if self._is_expired(expiry_time):
            del self.cache[key]
            del self.order[key]
            return None

        self.order.move_to_end(key)
        return value

    def __len__(self):
        # Count non-expired entries
        count = 0
        for key, (value, expiry_time) in self.cache.items():
            if not self._is_expired(expiry_time):
                count += 1
            else:
                # Optional: clean up as we go, but not required by spec
                pass
        return count

    def keys(self):
        # Return non-expired keys from LRU to MRU
        valid_keys = []
        # We iterate over the order (which is LRU -> MRU)
        for key in self.order:
            value, expiry_time = self.cache[key]
            if not self._is_expired(expiry_time):
                valid_keys.append(key)
            else:
                # Note: The spec says keys() returns keys of entries 
                # that are not expired. It doesn't explicitly say 
                # to delete them, but they shouldn't be in the list.
                pass
        return valid_keys

import heapq

class Scheduler:
    def __init__(self):
        # Stores task data: {name: (run_at, callback, every, sequence_number)}
        self.tasks = {}
        # Priority queue for (run_at, sequence_number, name)
        self.pq = []
        # Counter to maintain insertion order for stable sorting
        self.counter = 0
        # List of (name, exception)
        self.errors = []

    def schedule(self, name, run_at, callback, every=None):
        if name in self.tasks:
            raise ValueError("Task name must be unique")
        if every is not None and every <= 0:
            raise ValueError("Every must be greater than 0")

        self.tasks[name] = (run_at, callback, every, self.counter)
        heapq.heappush(self.pq, (run_at, self.counter, name))
        self.counter += 1

    def cancel(self, name):
        if name in self.tasks:
            del self.tasks[name]
            return True
        return False

    def pending(self):
        # Return list of (run_at, name) sorted by run_at then sequence
        # We filter out names that were cancelled but still in the heap
        sorted_tasks = []
        seen_names = set()

        # Since we need to maintain order of first scheduled, 
        # we iterate through the heap which is already sorted by (run_at, counter)
        for item in sorted(self.pq):
            run_at, seq, name = item
            if name in self.tasks:
                sorted_tasks.append((run_at, name))

        return sorted_tasks

    def run_due(self, now):
        run_names = []
        # Collect all tasks that are due
        due_tasks = []

        # We must extract from heap to ensure we process in correct order
        while self.pq and self.pq[0][0] <= now:
            run_at, seq, name = heapq.heappop(self.pq)
            if name in self.tasks:
                due_tasks.append((run_at, seq, name))
            else:
                # This was a cancelled task still in the heap
                continue

        # Process due tasks
        for run_at, seq, name in due_tasks:
            if name not in self.tasks:
                continue

            run_at, callback, every, _ = self.tasks[name]

            try:
                callback()
            except Exception as e:
                self.errors.append((name, e))

            run_names.append(name)

            if every is not None:
                # Reschedule repeating task
                new_run_at = run_at + every
                while new_run_at <= now:
                    new_run_at += every

                # Update task info and push back to heap
                self.tasks[name] = (new_run_at, callback, every, seq)
                heapq.heappush(self.pq, (new_run_at, seq, name))
            else:
                # Remove one-time task
                del self.tasks[name]

        return run_names

