    current_section = None

    for i, line in enumerate(lines, 1):
        stripped = line.strip()
        if not stripped or stripped.startswith(';') or stripped.startswith('#'):
            continue

        if stripped.startswith('[') and stripped.endswith(']'):
            name = stripped[1:-1].strip()
            if not name:
                raise ValueError(f"line {i}")
            if current_section is None:
                result[""] = {}

            if name not in result:
                result[name] = {}
            current_section = name
            continue

        if current_section is None:
            current_section = ""

        if '=' not in stripped:
            raise ValueError(f"line {i}")

        key_part, val_part = stripped.split('=', 1)
        key = key_part.strip()
        if not key:
            raise ValueError(f"line {i}")

        raw_val = val_part.strip()

        if raw_val.startswith('"'):
            # Quoted value
            content = ""
            i_ptr = 1
            found_end = False
            while i_ptr < len(raw_val):
                char = raw_val[i_ptr]
                if char == '\\':
                    if i_ptr + 1 < len(raw_val):
                        next_char = raw_val[i_ptr + 1]
                        if next_char == '"':
                            content += '"'
                            i_ptr += 2
                        elif next_char == '\\':
                            content += '\\'
                            i_ptr += 2
                        elif next_char == 'n':
                            content += '\n'
                            i_ptr += 2
                        elif next_char == 't':
                            content += '\t'
                            i_ptr += 2
                        else:
                            raise ValueError(f"line {i}")
                    else:
                        # Trailing backslash
                        content += '\\'
                        i_ptr += 1
                elif char == '"':
                    found_end = True
                    i_ptr += 1
                    break
                else:
                    content += char
                    i_ptr += 1

            if not found_end:
                raise ValueError(f"line {i}")

            # Check for trailing content
            remainder = raw_val[i_ptr:].strip()
            if remainder and not (remainder.startswith(';') or remainder.startswith('#')):
                raise ValueError(f"line {i}")

            final_val = content
        else:
            # Unquoted value
            # Find first ; or # preceded by whitespace
            comment_idx = -1
            for j in range(len(raw_val)):
                if raw_val[j] in (';', '#') and j > 0 and raw_val[j-1].isspace():
                    comment_idx = j
                    break

            if comment_idx != -1:
                final_val = raw_val[:comment_idx].strip()
            else:
                final_val = raw_val.strip()

        if current_section not in result:
            result[current_section] = {}
        result[current_section][key] = final_val

    # Ensure empty sections are represented if they were declared
    # The logic above handles this because current_section is updated
    # and result[name] = {} is initialized.

    # Clean up: result[""] should only exist if it has keys
    if "" in result and not result[""]:
        del result[""]

    return result

class OutOfStock(Exception):
    pass


class Inventory:
    def __init__(self, stock=None):
        self._stock = dict(stock) if stock is not None else {}

    def stock(self, item):
        return self._stock.get(item, 0)

    def add(self, item, qty):
        if qty <= 0:
            raise ValueError("Quantity must be positive")
        self._stock[item] = self.stock(item) + qty

    def remove(self, item, qty):
        if qty <= 0:
            raise ValueError("Quantity must be positive")
        current_stock = self.stock(item)
        if qty > current_stock:
            raise OutOfStock()
        self._stock[item] = current_stock - qty


def fulfil(inventory, order):
    if not order:
        return 0

    # Validate all quantities first
    for qty in order.values():
        if qty <= 0:
            raise ValueError("Quantity must be positive")

    # Create a backup to ensure "all or nothing"
    # Since we need to restore the exact state, we copy the current stock
    original_stock = inventory._stock.copy()
    total = 0

    try:
        for item, qty in order.items():
            inventory.remove(item, qty)
            total += qty
        return total
    except OutOfStock:
        # Restore state on failure
        inventory._stock = original_stock.copy()
        raise
